const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '入射光线' },
      { kind: 'text', payload: '法线' },
      { kind: 'text', payload: '反射光线' },
      { kind: 'text', payload: '反射角' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var s = Math.min(W / 640, H / 420);
    var ox = (W - 640 * s) / 2;
    var oy = (H - 420 * s) / 2;
    function X(x) { return ox + x * s; }
    function Y(y) { return oy + y * s; }
    function line(x1, y1, x2, y2) {
      return [['M', X(x1), Y(y1)], ['L', X(x2), Y(y2)]];
    }
    function tri(a, b, c) {
      return [['M', X(a[0]), Y(a[1])], ['L', X(b[0]), Y(b[1])], ['L', X(c[0]), Y(c[1])], ['Z']];
    }
    function head(tip, ux, uy, len, half) {
      var bx = tip[0] - ux * len;
      var by = tip[1] - uy * len;
      var px = -uy;
      var py = ux;
      return tri(tip, [bx + px * half, by + py * half], [bx - px * half, by - py * half]);
    }
    var SRC = [150, 120];
    var O = [320, 300];
    var REF = [490, 120];
    var li = Math.sqrt(Math.pow(O[0] - SRC[0], 2) + Math.pow(O[1] - SRC[1], 2));
    var uix = (O[0] - SRC[0]) / li;
    var uiy = (O[1] - SRC[1]) / li;
    var lr = Math.sqrt(Math.pow(REF[0] - O[0], 2) + Math.pow(REF[1] - O[1], 2));
    var urx = (REF[0] - O[0]) / lr;
    var ury = (REF[1] - O[1]) / lr;
    var pts = [];
    var R = 92;
    var N = 24;
    var t0 = -Math.PI / 2;
    var t1 = Math.atan2(REF[1] - O[1], REF[0] - O[0]);
    for (var i = 0; i <= N; i++) {
      var t = t0 + (t1 - t0) * (i / N);
      pts.push([X(O[0] + R * Math.cos(t)), Y(O[1] + R * Math.sin(t))]);
    }
    var ink = '#1f3350';
    var paths = [
      { id: 'surface', commands: line(60, 300, 580, 300) },
      { id: 'normal', commands: line(320, 300, 320, 88) },
      { id: 'incShaft', commands: line(SRC[0], SRC[1], O[0], O[1]) },
      { id: 'incHead', commands: head(O, uix, uiy, 16, 6.5) },
      { id: 'refShaft', commands: line(O[0], O[1], REF[0], REF[1]) },
      { id: 'refHead', commands: head(REF, urx, ury, 16, 6.5) },
      { id: 'angleArc', commands: visualSdk.polyline(pts) },
      { id: 'pointO', commands: visualSdk.circle(X(O[0]), Y(O[1]), 3.4 * s) }
    ];
    return {
      schemaVersion: 1,
      sceneId: 'reflection-law',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'surface', fill: ink, stroke: { width: 2 } },
          { type: 'path', pathId: 'normal', fill: ink, stroke: { width: 2, dash: [7, 5] } },
          { type: 'path', pathId: 'incShaft', fill: ink, stroke: { width: 2 } },
          { type: 'path', pathId: 'incHead', fill: ink },
          { type: 'path', pathId: 'refShaft', fill: ink, stroke: { width: 2 } },
          { type: 'path', pathId: 'refHead', fill: ink },
          { type: 'path', pathId: 'angleArc', fill: ink, stroke: { width: 2 } },
          { type: 'path', pathId: 'pointO', fill: ink },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: X(185), y: Y(206) }, hAlign: 'center', vAlign: 'middle', color: ink },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: X(333), y: Y(112) }, hAlign: 'left', vAlign: 'middle', color: ink },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: X(467), y: Y(194) }, hAlign: 'center', vAlign: 'middle', color: ink },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: X(364), y: Y(190) }, hAlign: 'center', vAlign: 'middle', color: ink }
        ]
      }
    };
  }
};
